INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (156, '3516', 'BIODANCE Mascarilla Facial Bio Collagen Real Deep Mask 1 unidad', '8809937361060', 13, 'ALTA', '34g', 'La Mascarilla Facial Biodance - Bio-Collagen Real Deep Mask es la solución ideal para quienes buscan una hidratación profunda y efectiva para todo tipo de piel. Con un peso neto de 34 g, esta mascarilla está formulada con ingredientes de alta calidad como colágeno, galactomyces, niacinamida y ácido hialurónico, que trabajan en sinergia para revitalizar y rejuvenecer la piel.

