INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (217, '21937', 'CELIMAX Limpiador Facial en Gel Dual Barrier Mild con Ceramidas', '8809606850499', 16, 'ALTA', '200ml', '', 'Limpiador facial en gel de pH bajo para el rostro que limpia suavemente sin alterar la barrera cutánea, formulado con 5 ceramidas esenciales y antioxidantes botánicos, que hidrata, protege y reduce la pérdida de agua desde el primer uso, ideal para todo tipo de piel, especialmente piel sensible o con barrera debilitada.



