INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (310, '19680', 'BEK Set de Cuidado Facial Nocturno', '', 19, 'ALTA', '', '', 'Set/kit de Coony que combina varios productos de la marca para una rutina completa. Marca coreana de cuidado facial y corporal, con mascarillas en hoja/hidrogel de un solo uso y dispositivos de belleza (rodillos, masajeadores, esferas frías).

Productos que incluye:

- Esponja Facial Konjac Original Cenizas de bambú (Negra)

