INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (383, '14701', 'COSRX SALICYLIC ACID DAILY GENTLE CLEANSER 150mL | Limpiador gentil con ácido salicílico y extractos botánicos', '8809416471112', 20, 'ALTA', '150ml', 'Cosrx es una marca que ofrece una variedad de productos para el cuidado de la piel facial. Si buscas protegerla y mantenerla en forma, esta puede ser una buena opción.

