INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (391, '14730', 'COSRX Sérum Iluminador The Vitamin C 23 Vitamina C Pura 20 g', '8800311121256', 20, 'ALTA', '20ml', 'Cosrx es una marca que ofrece una variedad de productos para el cuidado de la piel facial. Si buscas protegerla y mantenerla en forma, esta puede ser una buena opción.

Es hipoalergénico
