INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (397, '14651', 'COSRX Protector Solar Calmante en Crema Aloe Soothing SPF50+ PA+++ 50 ml', '8809416470191', 20, 'ALTA', '50ml', 'Disfruta sin preocupaciones del verano, protegiendo la piel de quienes más querés de los rayos ultravioletas del sol.

