INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (418, '4080', 'DAILY COMMA Loción Corporal Hidratante Perfumada Bello de Perfume', '8800273180087', 21, 'BAJA', '4080', 'Bello de Perfume Locion Corporal 500ml Sage Aqua perfumada. 

Aporta hidratación y deja la piel con una agradable fragancia de alta calidad. 

