INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (724, '3134', 'Lyuh Esther Curcumin Dire Film', '8809334863303', 28, 'BAJA', '3134', 'ESTHER FORMULA Lyuh Esther Curcumin Direct Film 30 láminas – Suplemento Antiinflamatorio con Curcumina Hidrosoluble

