INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (733, '25368', 'MADECA21 Ampolla Facial Calmante Teca Solution Capsule Complejo TECA 30 ml', '8806109182348', 47, 'BAJA', '25368', '', 'Ampolla fluida con cápsulas de la categoría de sueros y tratamientos para el tipo de tratamiento calmante y reparador en la zona del rostro y cuello. Formulado con el complejo patentado TECA (Titrated Extract of Centella Asiatica), Extracto de Centella Asiática y Ácido Hialurónico, ofrece el beneficio visible de una barrera de humedad reconstruida, alivio inmediato de la sensibilidad y una textura elástica de forma inmediata tras su aplicación diaria. Diseñada para todo tipo de piel, especialmente pieles sensibles y con el equilibrio de hidratación comprometido.



