INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (735, '26035', 'MADECA21 Crema Facial Unificadora del Tono Teca Toning Niacinamida 50 ml', '8806109102377', 47, 'BAJA', '26035', 'MADECA21 Teca Toning Cream 50ml – Crema Facial Unificadora de Tono e Iluminadora con Niacinamida

