INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (748, '6261', 'MANYO Leche Limpiadora Pure Cleansing con Soja 200 ml', '8809730959075', 48, 'BAJA', '6261', '', 'MEDICUBE SOYXIDILL 2IN1 TREATMENT 265 ml es el tratamiento capilar que tu rutina necesita. Este producto 2 en 1 combina el cuidado del cuero cabelludo y el cabello para fortalecer, nutrir y revitalizar tu pelo desde la raíz hasta las puntas.

