INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (783, '18798', 'MEDICUBE PDRN PEPTIDE GLOSSY LIP BALM Bálsamo Labial PDRN Peptide Glossy 10 g', '8800289474675', 50, 'ALTA', '10g', '', 'Bálsamo labial tratamiento con PDRN y péptidos que hidrata, repara y aporta un efecto glossy natural, dejando los labios más suaves, nutridos y visiblemente más saludables.

