INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (787, '3416', 'MEDICUBE Sérum Facial PDRN Pink Peptide Glow Instantáneo y Renovador 30 ml', '8800256108053', 50, 'ALTA', '30ml', '', 'Serum ligero con “pink glow” que combina PDRN (ADN de salmón o rosa), una mezcla de 5 tipos de péptidos, niacinamida, coenzima Q10 y extracto de hoja de albahaca sagrada (holy basil). Mejora la luminosidad, la textura y la elasticidad, mientras calma y fortalece la barrera cutánea. Diseñado para un efecto glow instantáneo y renovador.

