INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (788, '3384', 'MEDICUBE Tónico Facial Calmante PDRN Pink Cica Hidrata y Estimula Colágeno 250 ml', '8800256112234', 50, 'ALTA', '250ml', '', 'Tónico calmante y reparador con tecnología Glow Booster, aporta luminosidad, regula textura, refuerza la barrera y renueva la piel mientras calma la irritación, equilibra el tono y aporta hidratación profunda con un acabado translúcido y suave, ideal como base para el resto de la rutina.
