INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (798, '18802', 'MEDICUBE Mascarilla Facial Collagen Lifting Efecto Tensor 27 g', '8809517411741', 50, 'ALTA', '27g', '', 'Mascarilla facial lifting con colágeno que ayuda a mejorar la firmeza, elasticidad y aspecto general de la piel, dejando el rostro más tenso, hidratado y luminoso.

