INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (858, '3533', 'MIXSOON Aceite Limpiador Bean de Soja Fermentada 195 ml', '8809732911873', 54, 'ALTA', '195ml', 'BIENVENIDOS A SKINKO
