INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (873, '3642', 'MIXSOON Sérum Facial Soybean Milk Rico en Proteínas y Antioxidantes 50 ml', '8809732912528', 54, 'ALTA', '50ml', 'Mixsoon es una marca que ofrece una variedad de productos para el cuidado de la piel facial. Si buscás protegerla y mantenerla en forma, esta puede ser una buena opción.

