INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (894, '3700', 'OBGE Bálsamo Exfoliante en Barra para Puntos Negros y Control de Sebo', '8809567705623', 57, 'BAJA', '68', '', 'Bálsamo limpiador 3 en 1 en formato stick diseñado para exfoliar, controlar el exceso de sebo e hidratar la piel en un solo paso. Su formato práctico permite una aplicación directa y focalizada para lograr un rostro más suave, limpio y libre de impurezas.

