INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (895, '3699', 'OBGE Espuma Limpiadora Profunda Cloud Deep con Ácido Salicílico 150 ml', '8809567704862', 57, 'BAJA', '190', '', 'Espuma de limpieza facial profunda desarrollada por OBGE, marca coreana dedicada al cuidado y grooming masculino. Esta fórmula ayuda a retirar la suciedad acumulada y la grasitud del rostro, dejando la piel limpia, fresca y reconfortada en la rutina diaria.

