INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (916, '24963', 'Prelude Dante Sharpenable P 41', '8809672512598', 59, 'BAJA', '24963', '', 'REPRESENTATE OFICIAL DE SKIN1004 EN ARGENTINA

SKIN1004 con Presencia en más de 80 países
La marca con mayor sensibilidad para las texturas y sensoriales
