50ml.', '') ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, ean = EXCLUDED.ean, brand_id = EXCLUDED.brand_id, priority = EXCLUDED.priority, format = EXCLUDED.format, description_short = EXCLUDED.description_short, description_full = EXCLUDED.description_full;
