INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (979, '84790', 'SKIN1004 Aceite Limpiador Centella Light para Doble Limpieza Piel Sensible 200 ml', '8809576261110', 65, 'ALTA', '200ml', 'REPRESENTATE OFICIAL DE SKIN1004 EN ARGENTINA

