INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (986, '7516', 'SKIN1004 Crema Facial Reafirmante Hyalu-Teca Madagascar Centella 50 ml', '8809913834878', 65, 'ALTA', '', '7516', 'Redescubrí una piel más firme, hidratada y luminosa con SKIN1004 Madagascar Centella Hyalu-Teca Firming Cream, una crema facial desarrollada para reafirmar, mejorar la elasticidad y fortalecer la barrera cutánea gracias a una combinación de activos hidratantes, reparadores y antioxidantes.

