INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (987, '7510', 'SKIN1004 Kit Rutina Facial Luminosidad y Tratamiento Centella De Madagascar Edicion LATAM', '8809913834595', 65, 'ALTA', '', '7510', 'SKIN1004 Kit Rutina Centella Facial LATAM Edition
