INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (990, '7513', 'SKIN1004 Crema Facial Reparadora Centella Teca Madagascar 75 ml', '8809913834571', 65, 'ALTA', '', '7513', 'SKIN1004 Crema Reparadora Centella 75 ml
