INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (995, '18452', 'Sk1004 Madag Centella Cleanduo', '8809576261868', 65, 'ALTA', '120ml', 'Skin1004 Madagascar Centella Ampoule Kit 30ml X 4pcs incluye:

