INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (1011, '14789', 'SKIN1004 Contorno de Ojos Probio-Cica Bakuchiol 20 ml', '8809913830177', 65, 'ALTA', '20ml', '', 'Una crema suave para el contorno de ojos con centella fermentada y bakuchiol (retinol vegano) que estimula la producción de colágeno y reduce la apariencia de líneas de expresión y arrugas.

