INSERT INTO public.products (id, sku, name, ean, brand_id, priority, format, description_short, description_full) VALUES (1029, '84795', 'SKIN1004 Protector Solar Centella Air-Fit Plus SPF50+ PA++++ Filtro Físico con Color 50 ml', '8809576261301', 65, 'ALTA', '50ml', '', 'Protector solar mineral SPF50+ PA++++
